import React, { useState } from 'react';
import { Container, Button, Form, Table, Accordion, Card } from 'react-bootstrap';

const AcademicAdminDashboard = () => {
  const [step, setStep] = useState(1);
  const [semester, setSemester] = useState({ year: '', period: '' });
  const [courses, setCourses] = useState([]);
  const [groups, setGroups] = useState([]);
  const [students, setStudents] = useState([]);
  
  const periods = ['1', '2', 'V'];

  const handleNext = () => setStep(prev => prev + 1);
  const handleBack = () => setStep(prev => prev - 1);

  return (
    <Container className="mt-4 text-white">
      <h2>Inicializar Semestre</h2>

      {/* Paso 1: Crear Semestre */}
      {step === 1 && (
        <Card className="p-3 bg-dark text-white">
          <h4>Paso 1: Crear Semestre</h4>
          <Form>
            <Form.Group>
              <Form.Label>Año</Form.Label>
              <Form.Control
                type="number"
                value={semester.year}
                onChange={(e) => setSemester({ ...semester, year: e.target.value })}
              />
            </Form.Group>
            <Form.Group>
              <Form.Label>Periodo</Form.Label>
              <Form.Select
                value={semester.period}
                onChange={(e) => setSemester({ ...semester, period: e.target.value })}
              >
                <option value="">Seleccione</option>
                {periods.map(p => <option key={p}>{p}</option>)}
              </Form.Select>
            </Form.Group>
          </Form>
          <Button className="mt-3" onClick={handleNext}>Siguiente</Button>
        </Card>
      )}

      {/* Paso 2: Agregar Cursos al Semestre */}
      {step === 2 && (
        <Card className="p-3 bg-dark text-white">
          <h4>Paso 2: Agregar Cursos</h4>
          {/* Agregar componente o formulario para insertar cursos */}
          {/* Ej: Código, Nombre, Créditos, Carrera */}
          {/* Simulación de tabla */}
          <Table variant="dark" striped>
            <thead>
              <tr>
                <th>Código</th><th>Nombre</th><th>Créditos</th><th>Carrera</th>
              </tr>
            </thead>
            <tbody>
              {courses.map((course, index) => (
                <tr key={index}>
                  <td>{course.code}</td><td>{course.name}</td><td>{course.credits}</td><td>{course.major}</td>
                </tr>
              ))}
            </tbody>
          </Table>
          <Button onClick={handleBack}>Atrás</Button>
          <Button className="ms-2" onClick={handleNext}>Siguiente</Button>
        </Card>
      )}

      {/* Paso 3: Asignar Profesores y Matricular Estudiantes */}
      {step === 3 && (
        <Card className="p-3 bg-dark text-white">
          <h4>Paso 3: Asignar Profesores y Estudiantes</h4>
          {/* Formularios o tablas para asignar grupos, profesores, carnets */}
          <p>(Aquí se añadirían grupos, profesores asignados y estudiantes por carnet)</p>
          <Button onClick={handleBack}>Atrás</Button>
          <Button className="ms-2" onClick={handleNext}>Siguiente</Button>
        </Card>
      )}

      {/* Paso 4: Crear Estructura Documentos y Evaluaciones */}
      {step === 4 && (
        <Card className="p-3 bg-dark text-white">
          <h4>Paso 4: Crear Carpetas y Rubros</h4>
          <ul>
            <li>📁 Presentaciones</li>
            <li>📁 Quices</li>
            <li>📁 Exámenes</li>
            <li>📁 Proyectos</li>
          </ul>
          <p>Rubros de Evaluación:</p>
          <ul>
            <li>📊 Quices (30%)</li>
            <li>📊 Exámenes (30%)</li>
            <li>📊 Proyectos (40%)</li>
          </ul>
          <Button onClick={handleBack}>Atrás</Button>
          <Button variant="success" className="ms-2">Finalizar Inicialización</Button>
        </Card>
      )}
    </Container>
  );
};

export default AcademicAdminDashboard;
